SELECT COALESCE(w.warehouse_name, 'No Warehouse') AS warehouseName, d.drug_code AS drugCode, d.drug_name AS drugName, d.spec, d.unit, COALESCE(SUM(i.quantity), 0) AS currentStock, d.min_stock AS minStock, d.id AS drugId FROM drug d LEFT JOIN inventory i ON d.id = i.drug_id AND i.expire_date > NOW() AND i.quantity > 0 LEFT JOIN warehouse w ON i.warehouse_id = w.id WHERE d.min_stock IS NOT NULL
AND i.warehouse_id = #{warehouseId}
GROUP BY d.id, i.warehouse_id, w.warehouse_name HAVING currentStock <= d.min_stock ORDER BY w.warehouse_name, d.drug_name

SELECT COALESCE(SUM(quantity), 0) FROM inventory WHERE drug_id IN
#{drugId}
AND quantity > 0

SELECT COUNT(*) FROM inventory WHERE drug_id IN
#{drugId}
AND expire_date <= DATE_ADD(NOW(), INTERVAL 30 DAY) AND quantity > 0
